  if($path==='/admin/create-apikey'&&$method==='POST'){$b=request_body();$key='ab_'.bin2hex(random_bytes(20));app_db()->prepare('INSERT INTO api_keys(user_id,api_key,label,active,created) VALUES(?,?,?,1,UTC_TIMESTAMP())')->execute([$uid,$key,(string)($b['label']??'')]);json_out(['ok'=>true,'key'=>$key]);}
  if($path==='/admin/delete-apikey'&&$method==='POST'){$b=request_body();$q=app_db()->prepare('DELETE FROM api_keys WHERE api_key=? AND user_id=?');$q->execute([(string)($b['key']??''),$uid]);if(!$q->rowCount())fail('Key not found',404);json_out(['ok'=>true]);}
  if($path==='/admin/toggle-apikey'&&$method==='POST'){$b=request_body();app_db()->prepare('UPDATE api_keys SET active=? WHERE api_key=? AND user_id=?')->execute([!empty($b['active'])?1:0,(string)($b['key']??''),$uid]);json_out(['ok'=>true]);}
  if($path==='/admin/apikeys'&&$method==='GET'){$q=app_db()->prepare('SELECT api_key,label,active,usage_count,created,last_used FROM api_keys WHERE user_id=? ORDER BY created DESC LIMIT 200');$q->execute([$uid]);$rows=$q->fetchAll();foreach($rows as &$r){$r['key']=$r['api_key'];$r['usage']=$r['usage_count'];unset($r['api_key'],$r['usage_count']);}json_out($rows);}
  if($path==='/admin/users'&&$method==='GET'){require_admin($u);json_out(app_db()->query('SELECT u.id,u.username,u.email,u.role,u.is_active,u.created_at,u.last_login,(SELECT COUNT(*) FROM redirects r WHERE r.user_id=u.id)+(SELECT COUNT(*) FROM urls x WHERE x.user_id=u.id) AS total_links,(SELECT COUNT(*) FROM visits v WHERE v.user_id=u.id) AS total_visits FROM users u ORDER BY u.created_at DESC')->fetchAll());}
  if($path==='/admin/users/create'&&$method==='POST'){require_admin($u);$b=request_body();$name=trim((string)($b['username']??''));$email=strtolower(trim((string)($b['email']??'')));$pw=(string)($b['password']??'');if(!preg_match('/^[A-Za-z0-9_.-]{3,80}$/',$name))fail('Username must be 3–80 characters.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))fail('Valid email required.');if(strlen($pw)<10)fail('Password must be at least 10 characters.');try{app_db()->prepare("INSERT INTO users(username,email,password_hash,role,is_active,created_at) VALUES(?,?,?,'user',1,UTC_TIMESTAMP())")->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);}catch(PDOException $ex){if((string)$ex->getCode()==='23000')fail('Username or email already exists.',409);throw $ex;}json_out(['ok'=>true]);}
  if($path==='/admin/users/toggle'&&$method==='POST'){require_admin($u);$b=request_body();$id=(int)($b['id']??0);if($id===$uid)fail('You cannot suspend your own account.');$q=app_db()->prepare("UPDATE users SET is_active=? WHERE id=? AND role='user'");$q->execute([!empty($b['active'])?1:0,$id]);if(!$q->rowCount())fail('User not found or unchanged.',404);json_out(['ok'=>true]);}
  if($path==='/admin/users/delete'&&$method==='POST'){require_admin($u);$b=request_body();$id=(int)($b['id']??0);if($id===$uid)fail('You cannot delete your own account.');$q=app_db()->prepare("SELECT id FROM users WHERE id=? AND role='user'");$q->execute([$id]);if(!$q->fetch())fail('User not found.',404);$p=app_db();$p->beginTransaction();foreach(['visits','urls','redirects','blocked_ips','api_keys','user_settings'] as $tb)$p->prepare('DELETE FROM '.$tb.' WHERE user_id=?')->execute([$id]);$p->prepare('DELETE FROM users WHERE id=?')->execute([$id]);$p->commit();json_out(['ok'=>true]);}
